dashboard.definition:
{
	"visualizations": {
		"viz_EPUhCyRf": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "transparent",
				"strokeColor": "#0877a6"
			}
		},
		"viz_1v5Z17wK": {
			"type": "splunk.column",
			"title": "Host: $host_name$",
			"dataSources": {
				"primary": "ds_EEjlHznx"
			},
			"options": {
				"backgroundColor": "transparent"
			}
		},
		"viz_gVgfxMgi": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "transparent",
				"strokeColor": "#0877a6"
			}
		},
		"viz_b9aRU8GB": {
			"type": "splunk.sankey",
			"dataSources": {
				"primary": "ds_hkx9Pl59"
			},
			"title": "Sourcetype mapping",
			"options": {
				"backgroundColor": "transparent"
			}
		}
	},
	"dataSources": {
		"ds_EEjlHznx": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` host=$host_name$\r\n| fields source, sourcetype, host\r\n| timechart span=1d count by sourcetype",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"name": "Search_1"
		},
		"ds_hkx9Pl59": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` host=$host_name$\r\n| fields source, sourcetype, host\r\n| stats count by sourcetype, source",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"name": "Search_2"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"latest": "$global_time.latest$",
						"earliest": "$global_time.earliest$"
					}
				}
			}
		}
	},
	"inputs": {
		"input_global_trp": {
			"type": "input.timerange",
			"options": {
				"token": "global_time",
				"defaultValue": "-30d@d,now"
			},
			"title": "Global Time Range"
		}
	},
	"description": "",
	"title": "SAP Host Details",
	"layout": {
		"tabs": {
			"items": [
				{
					"layoutId": "layout_1",
					"label": "New tab"
				}
			]
		},
		"layoutDefinitions": {
			"layout_1": {
				"type": "absolute",
				"options": {
					"height": 840,
					"width": 1600,
					"display": "fit-to-width"
				},
				"structure": [
					{
						"item": "viz_gVgfxMgi",
						"type": "block",
						"position": {
							"x": 0,
							"y": 310,
							"w": 1590,
							"h": 500
						}
					},
					{
						"item": "viz_EPUhCyRf",
						"type": "block",
						"position": {
							"x": 0,
							"y": 0,
							"w": 1590,
							"h": 300
						}
					},
					{
						"item": "viz_1v5Z17wK",
						"type": "block",
						"position": {
							"x": 0,
							"y": 0,
							"w": 1580,
							"h": 300
						}
					},
					{
						"item": "viz_b9aRU8GB",
						"type": "block",
						"position": {
							"x": 0,
							"y": 310,
							"w": 1590,
							"h": 480
						}
					}
				]
			}
		},
		"globalInputs": [
			"input_global_trp"
		]
	}
}
